using namespace std;
int v[N],tr[N<<2],match[N],n,a;
int get(int i1,int i2) {
    if(match[i1]<match[i2]) return i2;
    return i1;
}
void build(int u,int l,int r) {
    if(l==r) {
        if(v[l]<=a) tr[u]=l;
        else tr[u]=0;
        return;
    }
    int mid=(l+r)>>1;
    build(u<<1,l,mid);
    build(u<<1|1,mid+1,r);
    tr[u]=get(tr[u<<1],tr[u<<1|1]);
    return;
}
void upd(int u,int l,int r,int x) {
    if(l==r) return;
    int mid=(l+r)>>1;
    if(x<=mid) upd(u<<1,l,mid,x);
    else upd(u<<1|1,mid+1,r,x);
    tr[u]=get(tr[u<<1],tr[u<<1|1]);
    return; 
}
int query(int u,int l,int r,int cl,int cr)
{
    if(l>=cl && r<=cr) return tr[u];
    int mid=(l+r)>>1,ans=0;
    if(mid>=cl) ans=get(ans,query(u<<1,l,mid,cl,cr));
    if(mid<cr) ans=get(ans,query(u<<1|1,mid+1,r,cl,cr));
    return ans;
}
