    if(dep[u]>dep[ans]) ans=u;
    for(auto v:e[u]) {
        if(v==fa) continue;
        dfs1(v,u);
    }
}
void dfs2(int u,int fa) {
    dep[u]=dep[fa]+1;
    if(dep[u]>dep[ans]) ans=u;
    for(auto v:e[u]) {
        if(v==fa) continue;
        dfs1(v,u);
    }
}
vector<int> ds;
vector<int> f[N];
bool dfs3(int u,int fa) {
    if(u==ans) {
        ds.push_back(u);
        return 1;
    }
    for(auto v:e[u]) {
        if(v==fa) continue;
        if(dfs3(v,u)) {
            ds.push_back(u);
            return 1;
        }
    }
    return 0;
}
int son[N],dp[N];
int leaf_num;
void dfs4(int u,int fa) {
    dp[u]=dep[u];
    if(dep[u]==dep[ans]) leaf_num++;
    for(auto v:e[u]) {
        if(v==fa) continue;
        dfs4(v,u);
        dp[u]=max(dp[u],dp[v]);
        if(dp[v]==dep[ans]) f[u].push_back(v),son[u]++;
    }
}
int dx[N];
int maxd;
void dfs5(int u) {
    if(dx[dep[u]]>son[u]) {
        if(dx[dep[u]]!=inf) for(int i=dep[u]+1;i<=maxd;i++) dx[i]=inf;
        dx[dep[u]]=son[u];
    }
    else if(dx[dep[u]]<son[u]) return;
    for(auto v:f[u]) {
        dfs5(v);
    }
}
