    bool operator <(const node &t) const{
        if(val!=t.val) return val<t.val;
        return id<t.id;
    }
}a[N];
int pos[N];
struct q1uple{
    int a,b,c;
    bool operator <(const q1uple &t) const{
        return (a==t.a)?((b==t.b)?b<t.b:c<t.c):a<t.a;
    }
};
void chk(int p,int &m1,int &m2,int &m3) {
    if(p<=m1) m3=m2,m2=m1,m1=p;
    else if(p<=m2) m3=m2,m2=p;
    else if(p<=m3) m3=p;
}
q1uple merge(q1uple x,q1uple y) {
    int m1=x.a,m2=x.b,m3=x.c;
    chk(y.a,m1,m2,m3);
    chk(y.b,m1,m2,m3);
    chk(y.c,m1,m2,m3);
    return {m1,m2,m3};
}
q1uple tr[N<<2];
void build(int u,int l,int r) {
    if(l==r) {
        tr[u]={a[l].id,inf,inf};
        return;
    }
    int mid=(l+r)>>1;
    build(u<<1,l,mid);
    build(u<<1|1,mid+1,r);
    tr[u]=merge(tr[u<<1],tr[u<<1|1]);
}
void mdf(int u,int l,int r,int x,int k) {
    if(l==r) {
        tr[u]={k,inf,inf};
        return;
    }
    int mid=(l+r)>>1;
    if(x<=mid) mdf(u<<1,l,mid,x,k);
    else mdf(u<<1|1,mid+1,r,x,k);
    tr[u]=merge(tr[u<<1],tr[u<<1|1]);
}
q1uple query(int u,int l,int r,int cl,int cr) {
    if(l>=cl && r<=cr) return tr[u];
    int mid=(l+r)>>1;
    q1uple ans={inf,inf,inf};
    if(mid>=cl) ans=merge(ans,query(u<<1,l,mid,cl,cr));
    if(mid<cr) ans=merge(ans,query(u<<1|1,mid+1,r,cl,cr));
    return ans;
}
